  "finely chopped",
  "canned drained",
  "canned",
  "processed",
  "chopped",
  "sliced",
  "julienne",
  "diced",
  "rings",
  "ring",
  "roasted",
  "boiled",
  "dehydrated",
  "juiced",
  "juice",
  "zest",
  "paste",
  "whole",
  "slit",
  "cut"
